package com.stacklab.controller;
import com.stacklab.dto.ApiDtos.*;import com.stacklab.service.UserService;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import jakarta.validation.Valid;import org.springdoc.core.annotations.ParameterObject;import org.springframework.data.domain.*;import org.springframework.data.web.PageableDefault;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users") @PreAuthorize("hasRole('ADMIN')") @SecurityRequirement(name="bearerAuth") public class UserController{private final UserService users;public UserController(UserService s){users=s;}@PostMapping @org.springframework.web.bind.annotation.ResponseStatus(org.springframework.http.HttpStatus.CREATED) public UserView create(@Valid @RequestBody UserCreate r){return users.create(r);}@GetMapping public Page<UserView> list(@RequestParam(required=false)String q,@ParameterObject @PageableDefault(size=20)Pageable page){return users.list(q,page);}@GetMapping("/{id}")public UserView get(@PathVariable Long id){return users.get(id);}@PutMapping("/{id}")public UserView update(@PathVariable Long id,@RequestBody UserUpdate r){return users.update(id,r);}@DeleteMapping("/{id}")@org.springframework.web.bind.annotation.ResponseStatus(org.springframework.http.HttpStatus.NO_CONTENT)public void deactivate(@PathVariable Long id){users.deactivate(id);}}
